const RBB_INFO={id:"rash-behari-bose",title:"Rash Behari Bose",quickStats:[{label:"Born",value:"1886, Subaldaha, Bengal",icon:"📍"},{label:"Died",value:"1945, Tokyo, Japan",icon:"🕊️"},{label:"Known For",value:"Founding the INA's Precursor",icon:"🎖️"},{label:"Key Country",value:"Japan (Exile)",icon:"🇯🇵"},{label:"Successor",value:"Subhas Chandra Bose",icon:"➡️"},{label:"Movement",value:"Indian Independence Movement",icon:"🇮🇳"}]},HISTORY_TEXT={title:"From Delhi Conspiracy to Decades in Exile",paragraphs:["Rash Behari Bose was an Indian revolutionary who became involved in anti-colonial activities in the early 20th century. He is best known for his role in the 1912 Delhi–Lahore Conspiracy, an assassination attempt on the then Viceroy of India, Lord Hardinge, during a ceremonial procession in Delhi.","After the attempt, Bose evaded capture by British authorities for years while continuing to organize revolutionary activity, before ultimately escaping to Japan in 1915 under an assumed identity to avoid arrest.","Living in exile in Japan for the remainder of his life, Bose built relationships with Japanese political and military figures, married into a Japanese family, and became a Japanese citizen, all while continuing to advocate internationally for Indian independence.","Rash Behari Bose is historically significant for founding the Indian Independence League and organizing the first iteration of what would become the Indian National Army (INA) among Indian expatriates and prisoners of war in Southeast Asia. In 1943, he formally handed over leadership of the INA to Subhas Chandra Bose, who expanded and led it to greater international prominence."]},TIMELINE_EVENTS=[{era:"1886",title:"Born in Bengal",description:"Rash Behari Bose was born in Subaldaha, Bengal Presidency, British India."},{era:"1912",title:"Delhi–Lahore Conspiracy",description:"Involved in an assassination attempt on Viceroy Lord Hardinge during a procession in Delhi."},{era:"1915",title:"Escape to Japan",description:"Fled India under an assumed identity to avoid arrest by British authorities, beginning a life in exile."},{era:"1923",title:"Japanese Citizenship",description:"Became a naturalized Japanese citizen while continuing to advocate for Indian independence from abroad."},{era:"1942",title:"Indian Independence League",description:"Played a central role in founding and organizing the Indian Independence League in East and Southeast Asia."},{era:"1942–43",title:"First Indian National Army",description:"Helped organize an early Indian National Army from Indian soldiers and civilians in Southeast Asia."},{era:"1943",title:"Handover to Subhas Chandra Bose",description:"Formally transferred leadership of the INA to Subhas Chandra Bose, who reorganized and led it forward."},{era:"1945",title:"Death in Tokyo",description:"Rash Behari Bose passed away in Tokyo, shortly before the end of World War II."}],INTERNATIONAL_ACTIVITIES=[{title:"Exile in Japan",description:"Spent three decades in Japan, building political relationships that would later support the Indian independence cause internationally."},{title:"Pan-Asian Networks",description:"Engaged with pan-Asianist political circles in Japan, connecting Indian independence aspirations with broader anti-colonial sentiment in Asia."},{title:"Organizing the Diaspora",description:"Worked to mobilize and organize the Indian diaspora across East and Southeast Asia in support of independence."},{title:"Bridge to the INA's Global Chapter",description:"His organizing work laid essential international groundwork that Subhas Chandra Bose later built upon for the INA's larger campaigns."}],INA_TEXT={paragraphs:["Following the fall of British Malaya and Singapore to Japanese forces in 1942, a large number of Indian soldiers who had served in the British Indian Army became prisoners of war. Rash Behari Bose, working with the Indian Independence League, played a key role in organizing these soldiers, along with local Indian civilians, into the first Indian National Army.","This early INA was formed with the stated goal of fighting for Indian independence, in coordination with Japanese support during World War II. However, organizational and political challenges limited its early effectiveness.","In 1943, Rash Behari Bose formally handed over leadership of the movement and the INA to Subhas Chandra Bose, who had recently arrived in Southeast Asia. Under his leadership, the INA — commonly known as the Azad Hind Fauj — was reorganized, expanded, and became far more widely known internationally, including through the establishment of the Provisional Government of Free India.","Rash Behari Bose is historically credited as the founding organizer whose groundwork made this larger, more famous chapter of the INA's history possible."]},REFERENCES=[{text:"Government of India — National Archives records on the Delhi Conspiracy Case.",link:"#"},{text:"Fay, P. W. — 'The Forgotten Army: India's Armed Struggle for Independence.'",link:"#"},{text:"Bose, R. B. — historical biographical accounts of his life in Japan.",link:"#"},{text:"Netaji Research Bureau — archival material on the INA's formation.",link:"#"}];